return {["scripts/items/kabura_quiver.lua"]={["Path"]="scripts/items/kabura_quiver.lua",["SHA256"]="f4e9da73b9ba6a4970462207311f22da85f0c8e6380c874414af8979faa479d8",["Text"]="-----------------------------------\n-- ID: 5332\n-- Kabura Quiver\n-- When used, you will obtain one stack of Kabura Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.KABURA_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/kalamar.lua"]={["Path"]="scripts/items/kalamar.lua",["SHA256"]="dc852bf7d83fb1ee93f1668c461d927c93d871de04db6c3ed40a2e7c1444b892",["Text"]="-----------------------------------\n-- ID: 5448\n-- Item: Kalamar\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 3\n-- Mind -5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.MND, -5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/kaplumbaga.lua"]={["Path"]="scripts/items/kaplumbaga.lua",["SHA256"]="c2b48396613c1f48f10361e6f9c43574dce5caa8891943170fc9b1dc0edca0d7",["Text"]="-----------------------------------\n-- ID: 5464\n-- Item: Kaplumbaga\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 3\n-- Mind -5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.MND, -5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/karura_hachigane.lua"]={["Path"]="scripts/items/karura_hachigane.lua",["SHA256"]="76aaecf44121ac46a07c77456c62d9ca51dc910f2e9ca7a13c5c5abdb80f1df6",["Text"]="-----------------------------------\n-- ID: 16154\n-- Karura Hachigane\n-- Pet mod via latent effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\nlocal listenerPrefix = 'PET_MOD_LATENT'\nlocal latentPetId = xi.petId.GARUDA\nlocal latentMods =\n{\n    { xi.mod.ATT, 10 },\n    { xi.mod.DEF, 10 },\n}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemEquip  = function(user, item)\n    local listenerName = fmt('{}_{}', listenerPrefix, item:getID())\n    xi.itemUtils.handlePetLatentMods(user, latentPetId, latentMods, true)\n\n    user:addListener('MAGIC_STATE_EXIT', listenerName, function(player, spell)\n        if spell:getSpellGroup() == xi.magic.spellGroup.SUMMONING then\n            xi.itemUtils.handlePetLatentMods(user, latentPetId, latentMods, true)\n        end\n    end)\nend\n\nitemObject.onItemUnequip = function(user, item)\n    local listenerName = fmt('{}_{}', listenerPrefix, item:getID())\n    xi.itemUtils.handlePetLatentMods(user, latentPetId, latentMods, false)\n\n    user:removeListener(listenerName)\nend\n\nreturn itemObject\n"},["scripts/items/kawahori_kabuto.lua"]={["Path"]="scripts/items/kawahori_kabuto.lua",["SHA256"]="1dce8f355ba91ad46975bee7c9b0abc609b02e76b6fdd61f3dab6835837a9cca",["Text"]="-----------------------------------\n-- ID: 16071\n-- Item: kawahori_kabuto\n-- Effect: blindness\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if not target:hasStatusEffect(xi.effect.BLINDNESS) then\n        target:addStatusEffect(xi.effect.BLINDNESS, { power = 200, duration = 60 * 10, origin = user })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/kayabaligi.lua"]={["Path"]="scripts/items/kayabaligi.lua",["SHA256"]="3ee0ff0e5b123c5fba028fd7302197dddd82cf2b4a336037a1079d1b3adb9ec8",["Text"]="-----------------------------------\n-- ID: 5460\n-- Item: Kayabaligi\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 4\n-- Mind -6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.MND, -6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/kazham_earring.lua"]={["Path"]="scripts/items/kazham_earring.lua",["SHA256"]="da4e241ac3ea6b043f9696e1e5c48d2da750a449b4b0d5f50d2207fbf8ef6e81",["Text"]="-----------------------------------\n-- ID: 16046\n-- Kazham Earring\n-- Enchantment: \"Teleport\" (Kazham)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.KAZHAM_EARRING, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/kazham_pineapple.lua"]={["Path"]="scripts/items/kazham_pineapple.lua",["SHA256"]="f6754d4e732208959dfb9a0980d721730fb941390451e7dd782635728089a114",["Text"]="-----------------------------------\n-- ID: 4432\n-- Item: kazham_pineapple\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility -5\n-- Intelligence 3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, -5)\n    effect:addMod(xi.mod.INT, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/keen_zaghnal.lua"]={["Path"]="scripts/items/keen_zaghnal.lua",["SHA256"]="8df3213234bd8bbdbbe2c0cd414b5f81e0ca5e50c003e9b7e98886cd10291949",["Text"]="-----------------------------------\n-- ID: 18067\n-- Equip: Keen Zaghnal\n-- Enchantment: Accuracy +3\n-- Enchantment will wear off if weapon is unequipped.\n-- Effect lasts for 30 minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ACCURACY_BOOST, xi.effectSourceType.EQUIPPED_ITEM, xi.item.KEEN_ZAGHNAL) ~= nil then\n        target:delStatusEffect(xi.effect.ACCURACY_BOOST, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.KEEN_ZAGHNAL)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.KEEN_ZAGHNAL) then\n        target:addStatusEffect(xi.effect.ACCURACY_BOOST, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.KEEN_ZAGHNAL })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.ACC, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/keppu.lua"]={["Path"]="scripts/items/keppu.lua",["SHA256"]="973db7896b6ea94e4622c52945077c4495e443dc5b049e8450f493ce889bb4a8",["Text"]="-----------------------------------\n-- ID: 17784\n-- Item: Keppu\n-- Additional effect: wind damage depending on ammo\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local damageRange = xi.additionalEffect.getConsumableAmmoItemDamageRange(xi.element.WIND, actor:getEquipID(xi.slot.AMMO))\n\n    if not damageRange then\n        return 0, 0, 0\n    end\n\n    local pTable =\n    {\n        chance          = 15, -- TODO: guessed based on rapier/sword proc rates\n        basePower       = math.randomInt(damageRange[1], damageRange[2]),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.WIND,\n        canMAB          = false,\n        canResist       = true,\n        lowestResist    = 0.5,\n        useAmmo         = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/keppu_+1.lua"]={["Path"]="scripts/items/keppu_+1.lua",["SHA256"]="da28d01e0716fe7e4a08fc4185aa0162eb3a40f1082bcd04ff2d620c58f2c7b5",["Text"]="-----------------------------------\n-- ID: 17785\n-- Item: Keppu +1\n-- Additional effect: wind damage depending on ammo\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local damageRange = xi.additionalEffect.getConsumableAmmoItemDamageRange(xi.element.WIND, actor:getEquipID(xi.slot.AMMO))\n\n    if not damageRange then\n        return 0, 0, 0\n    end\n\n    local pTable =\n    {\n        chance          = 15, -- TODO: guessed based on rapier/sword proc rates\n        basePower       = math.randomInt(damageRange[1], damageRange[2]),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.WIND,\n        canMAB          = false,\n        canResist       = true,\n        lowestResist    = 0.5,\n        useAmmo         = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/key_ring_belt.lua"]={["Path"]="scripts/items/key_ring_belt.lua",["SHA256"]="5035bcd403c864cd4e80aa2d8b29146e2e970faa7539f5185521c8e018c69456",["Text"]="-----------------------------------\n-- ID: 15880\n-- key_ring_belt\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.SKELETON_KEY, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/king_truffle.lua"]={["Path"]="scripts/items/king_truffle.lua",["SHA256"]="3539362701b0efb740b23fc965557360194a5d77827536b1832bcd5651041fe5",["Text"]="-----------------------------------\n-- ID: 4386\n-- King Truffle\n--  5 Minutes, food effect, All Races\n-----------------------------------\n-- Strength -6\n-- Mind     +4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, -6)\n    effect:addMod(xi.mod.MND, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/kingdom_earring.lua"]={["Path"]="scripts/items/kingdom_earring.lua",["SHA256"]="d24042ea311cd421ba7f58376169d7a33b683080689aff637b8e402bea048065",["Text"]="-----------------------------------\n-- ID: 16039\n-- Kingdom Earring\n-- Enchantment: \"Teleport\" (Southern San d'Oria)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.KINGDOM_EARRING, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/kingdom_signet_staff.lua"]={["Path"]="scripts/items/kingdom_signet_staff.lua",["SHA256"]="31316416f1cccb8c30d1b52fc2acb934adfe3308f81a6d469b379b03a5c87d42",["Text"]="-----------------------------------\n-- ID: 17583\n-- Item: Kingdom Signet Staff\n-- Effect: Signet\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getNation() ~= xi.nation.SANDORIA then\n        return xi.msg.basic.ITEM_CANNOT_USE_ON\n    end\n\n    -- If target's current region is not a conquest region or not a nation city involved with conquest\n    if target:getCurrentRegion() > xi.region.JEUNO then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    -- Can only use on targets within party or self\n    if target:getID() ~= caster:getID() then\n        if\n            caster:getPartyLeader() == nil or\n            target:getPartyLeader():getID() ~= caster:getPartyLeader():getID()\n        then\n            return xi.msg.basic.ITEM_CANNOT_USE_ON\n        end\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:delStatusEffectsByFlag(xi.effectFlag.INFLUENCE, true)\n    target:addStatusEffect(xi.effect.SIGNET, { duration = 18000, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/kingdom_stables_collar.lua"]={["Path"]="scripts/items/kingdom_stables_collar.lua",["SHA256"]="aec9be280701fd710470bd22534e3694aacde5ce19a354b95ed37ffdbe18412f",["Text"]="-----------------------------------\n-- ID: 13179\n-- Item: Kingdom Stables Collar\n-- Teleports to Chocobo Stables (San d'Oria)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if not target:hasVisitedZone(xi.zone.SOUTHERN_SAN_DORIA) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.CHOCO_SANDORIA, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/kinkobo.lua"]={["Path"]="scripts/items/kinkobo.lua",["SHA256"]="5e0c3c5750f6d9642f33dcbac2cceb5f644606371ead0849e652b666431e72e0",["Text"]="-----------------------------------\n-- ID: 17592\n-- Item: Kinkobo\n-- Enchantment: Subtle Blow\n-- Duration: 60 Mins\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if not target:hasStatusEffect(xi.effect.ENCHANTMENT) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 3600, origin = user, subType = 17592 })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.SUBTLE_BLOW, 20)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/kitron.lua"]={["Path"]="scripts/items/kitron.lua",["SHA256"]="cf23684f064a6f5c07369d57e7c43e5c9c2644c9bc347b9ec73f7e289a0595c9",["Text"]="-----------------------------------\n-- ID: 4273\n-- Item: Kitron\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility -6\n-- Intelligence 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, -6)\n    effect:addMod(xi.mod.INT, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/kitron_macaron.lua"]={["Path"]="scripts/items/kitron_macaron.lua",["SHA256"]="136a6b11149a625883f854145de32aa7e12be934e06e5ea30d741111134158fc",["Text"]="-----------------------------------\n-- ID: 5781\n-- Item: kitron_macaron\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Increases rate of synthesis success +7%\n-- Increases synthesis skill gain rate +7%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.SYNTH_SUCCESS_RATE, 7)\n    effect:addMod(xi.mod.SYNTH_SKILL_GAIN, 7)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/kitron_snow_cone.lua"]={["Path"]="scripts/items/kitron_snow_cone.lua",["SHA256"]="b3a946d86912928c771a8ad573019ed2c1b77ef1d9b9cf9aca3b66cc62167ba9",["Text"]="-----------------------------------\n-- ID: 5711\n-- Item: kitron_snow_cone\n-- Food Effect: 5 Min, All Races\n-----------------------------------\n-- MP +15% (cap 15)\n-- Intelligence 2\n-- Wind resistance +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 15)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 15)\n    effect:addMod(xi.mod.INT, 2)\n    effect:addMod(xi.mod.WIND_MEVA, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/kitty_rod.lua"]={["Path"]="scripts/items/kitty_rod.lua",["SHA256"]="d0d5026e3a6530e9a49be6707fbe75f0c0bc0312cb60eca7d9cc1043f5578f29",["Text"]="-----------------------------------\n-- ID: 18871\n-- Kitty Rod\n-- Enchantment: 60Min, Costume - Mithra child (Blue)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 183, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/klimaform_schema.lua"]={["Path"]="scripts/items/klimaform_schema.lua",["SHA256"]="dffc7fde8cab569afcb21810e9c2a293d5d9f0e208169661cf2d04e81e1f228f",["Text"]="-----------------------------------\n-- ID: 6058\n-- Klimaform Schema\n-- Teaches the black magic Klimaform\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.KLIMAFORM)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.KLIMAFORM)\nend\n\nreturn itemObject\n"},["scripts/items/koccos_earring.lua"]={["Path"]="scripts/items/koccos_earring.lua",["SHA256"]="4767e2fd7927478a3876e3952426301ce968a3d620fa25fd913201b5bcbd87fb",["Text"]="-----------------------------------\n-- ID: 15998\n-- Kocco's Earring\n-- This earring functions in the same way as the spell Reraise II.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local duration = 7200\n    target:delStatusEffect(xi.effect.RERAISE)\n    target:addStatusEffect(xi.effect.RERAISE, { power = 2, duration = duration, origin = user })\n    target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.RERAISE)\nend\n\nreturn itemObject\n"},["scripts/items/koen.lua"]={["Path"]="scripts/items/koen.lua",["SHA256"]="5218acab4f199f06e798744ab5f36592eb18ec583f2695b7f4382c5cfb5d249b",["Text"]="-----------------------------------\n-- ID: 17828\n-- Item: Koen\n-- Enchantment: Enfire\n-- Duration:\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 7, -- TODO: Homura scales with INT. does this?\n        basePower      = math.randomInt(6, 8),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nitemObject.onItemCheck = function(target, user)\n    if target:getStatusEffectBySource(xi.effect.ENFIRE, xi.effectSourceType.EQUIPPED_ITEM, xi.item.KOEN) ~= nil then\n        target:delStatusEffect(xi.effect.ENFIRE, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.KOEN)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.KOEN) then\n        target:addStatusEffect(xi.effect.ENFIRE, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.KOEN })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    local magicskill = target:getSkillLevel(xi.skill.ENHANCING_MAGIC)\n    local potency = 0\n\n    if magicskill <= 200 then\n        potency = 3 + math.floor(6 * magicskill / 100)\n    elseif magicskill > 200 then\n        potency = 5 + math.floor(5 * magicskill / 100)\n    end\n\n    potency = utils.clamp(potency, 3, 25)\n\n    effect:addMod(xi.mod.ENSPELL, xi.element.FIRE)\n    effect:addMod(xi.mod.ENSPELL_DMG, potency)\n    effect:addMod(xi.mod.ENSPELL_CHANCE, 100)\nend\n\n-- empty function required for onEffectGain to work\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/koga_shuriken_pouch.lua"]={["Path"]="scripts/items/koga_shuriken_pouch.lua",["SHA256"]="7f75e8ae85aef450a7d81fba2686ce97da5f0c37b9545a9e9f45c26018bf41ca",["Text"]="-----------------------------------\n-- ID: 6300\n-- Item: Koga Shr. Pouch\n-- When used, you will obtain one stack of Koga Shurikens\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.KOGA_SHURIKEN, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/kohlrouladen.lua"]={["Path"]="scripts/items/kohlrouladen.lua",["SHA256"]="df219f260f30a1085b2b6e5e7c793c5db6b376a43984008004a45c67c443d9f9",["Text"]="-----------------------------------\n-- ID: 5760\n-- Item: kohlrouladen\n-- Food Effect: 3hr, All Races\n-----------------------------------\n-- Strength 3\n-- Agility 3\n-- Intelligence -5\n-- RACC +8% (cap 60)\n-- RATT +14% (cap 65)\n-- Enmity -4\n-- Subtle Blow +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 3)\n    effect:addMod(xi.mod.AGI, 3)\n    effect:addMod(xi.mod.INT, -5)\n    effect:addMod(xi.mod.FOOD_RACCP, 8)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 60)\n    effect:addMod(xi.mod.FOOD_RATTP, 14)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 65)\n    effect:addMod(xi.mod.ENMITY, -4)\n    effect:addMod(xi.mod.SUBTLE_BLOW, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/kohlrouladen_+1.lua"]={["Path"]="scripts/items/kohlrouladen_+1.lua",["SHA256"]="2d56f6f38e965cd7f6a2d93cb2dbf857d68d40c3624c6a6bfaa2ebb201148d12",["Text"]="-----------------------------------\n-- ID: 5761\n-- Item: kohlrouladen +1\n-- Food Effect: 4hr, All Races\n-----------------------------------\n-- Strength 4\n-- Agility 4\n-- Intelligence -4\n-- RACC +10% (cap 65)\n-- RATT +16% (cap 70)\n-- Enmity -5\n-- Subtle Blow +6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 4)\n    effect:addMod(xi.mod.AGI, 4)\n    effect:addMod(xi.mod.INT, -4)\n    effect:addMod(xi.mod.FOOD_RACCP, 10)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 65)\n    effect:addMod(xi.mod.FOOD_RATTP, 16)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 70)\n    effect:addMod(xi.mod.ENMITY, -5)\n    effect:addMod(xi.mod.SUBTLE_BLOW, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/komanezumi.lua"]={["Path"]="scripts/items/komanezumi.lua",["SHA256"]="869d997a66b3e86776e5cad1bb4bd717f2ed20f31072586abc0c10b919f36a07",["Text"]="-----------------------------------\n-- ID: 6268\n-- Komanezumi\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/kongou_inaho.lua"]={["Path"]="scripts/items/kongou_inaho.lua",["SHA256"]="bec5f4032d32b217cc1572c7061459361dd9ccb878c8c8178df8f3a2ada0a438",["Text"]="-----------------------------------\n-- ID: 4184\n-- Kongou Inaho\n-- A sparkler-type firework appears in the user's hand\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/konigskuchen.lua"]={["Path"]="scripts/items/konigskuchen.lua",["SHA256"]="02692179babe9040f12ff6ef7e7f20ed369663308acf76d995879d802238c33b",["Text"]="-----------------------------------\n-- ID: 5614\n-- Item: konigskuchen\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Health 8\n-- Magic % 3\n-- Magic Cap 13\n-- Intelligence 2\n-- hMP +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 8)\n    effect:addMod(xi.mod.FOOD_MPP, 3)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 13)\n    effect:addMod(xi.mod.INT, 2)\n    effect:addMod(xi.mod.MPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/konron_hassen.lua"]={["Path"]="scripts/items/konron_hassen.lua",["SHA256"]="13b1e57387596621586cd32fecce67c00285781ccde4c5268f1f706cd26e1d42",["Text"]="-----------------------------------\n-- ID: 4183\n-- Konron Hassen\n-- A fountain-type firework appears on the ground\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/kupo_rod.lua"]={["Path"]="scripts/items/kupo_rod.lua",["SHA256"]="ccb95594c204983c14a899af36eb841c114bbca227fcff0bee667e92c51acce2",["Text"]="-----------------------------------\n-- ID: 21074\n-- Item: Kupo Rod\n-- Enchantment: Moogle Blessing (removes Weakness)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:hasStatusEffect(xi.effect.WEAKNESS) then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    else\n        return 0\n    end\nend\n\nitemObject.onItemUse = function(target)\n    if target:hasStatusEffect(xi.effect.WEAKNESS) then\n        target:delStatusEffect(xi.effect.WEAKNESS)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/kupofrieds_ring.lua"]={["Path"]="scripts/items/kupofrieds_ring.lua",["SHA256"]="48e51cb02334b7530cf9bdd0abe416f9f7506f6df3cb5caaa5ab7c8a576d9afa",["Text"]="-----------------------------------\n-- ID: 15793\n-- Item: Anniversary Ring\n-- Experience point bonus\n-----------------------------------\n-- Bonus: +100%\n-- Duration: 1440 min/24hr\n-- Max bonus: 30000 exp\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:hasStatusEffect(xi.effect.DEDICATION) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.DEDICATION\n    local power     = 100\n    local duration  = 86400\n    local subpower  = 30000\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/kyofu.lua"]={["Path"]="scripts/items/kyofu.lua",["SHA256"]="25397664af6facc9c1dc5f60a94f53f695152eebe443a060d1724c177040c1f8",["Text"]="-----------------------------------\n-- ID: 17780\n-- Item: Kyofu\n-- Additional effect: wind damage depending on ammo\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local damageRange = xi.additionalEffect.getConsumableAmmoItemDamageRange(xi.element.WIND, actor:getEquipID(xi.slot.AMMO))\n\n    if not damageRange then\n        return 0, 0, 0\n    end\n\n    local pTable =\n    {\n        chance          = 15, -- TODO: guessed based on rapier/sword proc rates\n        basePower       = math.randomInt(damageRange[1], damageRange[2]),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.WIND,\n        canMAB          = false,\n        canResist       = true,\n        lowestResist    = 0.5,\n        useAmmo         = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/kyofu_+1.lua"]={["Path"]="scripts/items/kyofu_+1.lua",["SHA256"]="9ee77836843e0e40753b253c367a5e1ce1d6183e9967851c54c4e46eb890722b",["Text"]="-----------------------------------\n-- ID: 17781\n-- Item: Kyofu +1\n-- Additional effect: wind damage depending on ammo\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local damageRange = xi.additionalEffect.getConsumableAmmoItemDamageRange(xi.element.WIND, actor:getEquipID(xi.slot.AMMO))\n\n    if not damageRange then\n        return 0, 0, 0\n    end\n\n    local pTable =\n    {\n        chance          = 15, -- TODO: guessed based on rapier/sword proc rates\n        basePower       = math.randomInt(damageRange[1], damageRange[2]),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.WIND,\n        canMAB          = false,\n        canResist       = true,\n        lowestResist    = 0.5,\n        useAmmo         = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/la_theine_cabbage.lua"]={["Path"]="scripts/items/la_theine_cabbage.lua",["SHA256"]="50757988ac4d980ff94b6fd7de6670d3544b87e874218a056a243ac6c71c53de",["Text"]="-----------------------------------\n-- ID: 4366\n-- Item: la_theine_cabbage\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Agility 1\n-- Vitality -3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.VIT, -3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/lamiabane.lua"]={["Path"]="scripts/items/lamiabane.lua",["SHA256"]="18bac76f2a5b63b821e50156afcc9c3ed41aa8047e9a5ac2f61aa9682b8f1add",["Text"]="-----------------------------------\n-- ID: 18693\n-- Item: Lamiabane\n-- Item Effect: Enchantment: Refresh +1\n-- Duration: 60 Minutes\n-- Only usable in Arrapago Reef, Halvung, or Mamook. Effect lost upon zoning or unequipping.\n-- https://wiki.ffo.jp/html/4402.html\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local zoneId = target:getZoneID()\n\n    if\n        zoneId == xi.zone.ARRAPAGO_REEF or\n        zoneId == xi.zone.HALVUNG or\n        zoneId == xi.zone.MAMOOK\n    then\n        return 0\n    else\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.LAMIABANE) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 3600, origin = user, flag = xi.effectFlag.ON_ZONE, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.LAMIABANE })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.REFRESH, 1)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.LAMIABANE)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/leaf_bench.lua"]={["Path"]="scripts/items/leaf_bench.lua",["SHA256"]="d3a72a73bb4ccfca3dc42f81f8c1789c0844a4b9611c657ab3ddc2119f9e3052",["Text"]="-----------------------------------\n-- ID: 6412\n-- Item: Leaf Bench\n-- Item Effect: Grant Leaf bench key item\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nlocal keyItemId = xi.keyItem.LEAF_BENCH\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasKeyItem(keyItemId) then\n        return xi.msg.basic.ALREADY_HAVE_KEY_ITEM, 0, keyItemId\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addKeyItem(keyItemId)\n    target:messageBasic(xi.msg.basic.OBTAINED_KEY_ITEM, 6412, keyItemId)\nend\n\nreturn itemObject\n"},["scripts/items/lebkuchen_house.lua"]={["Path"]="scripts/items/lebkuchen_house.lua",["SHA256"]="93ee7704d72642715d804b66919d4a2315af761fa96f71a32b928189c93a29df",["Text"]="-----------------------------------\n-- ID: 5616\n-- Item: lebkuchen_house\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- HP +8\n-- MP +10% (cap 45)\n-- INT +3\n-- hHP +2\n-- hMP +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 8)\n    effect:addMod(xi.mod.FOOD_MPP, 10)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 45)\n    effect:addMod(xi.mod.INT, 3)\n    effect:addMod(xi.mod.HPHEAL, 2)\n    effect:addMod(xi.mod.MPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/lebkuchen_manse.lua"]={["Path"]="scripts/items/lebkuchen_manse.lua",["SHA256"]="4cdde5d491c146a14818a30cda2927e7b9550ddfa1cbc08100665c340700c91d",["Text"]="-----------------------------------\n-- ID: 5617\n-- Item: lebkuchen_manse\n-- Food Effect: 240Min, All Races\n-----------------------------------\n-- HP +10\n-- MP +10% (cap 55)\n-- INT +4\n-- hHP +3\n-- hMP +2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.FOOD_MPP, 10)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 55)\n    effect:addMod(xi.mod.INT, 4)\n    effect:addMod(xi.mod.HPHEAL, 3)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/leremieu_salad.lua"]={["Path"]="scripts/items/leremieu_salad.lua",["SHA256"]="f1440eaf9c2e494d38d416e375313b5d03796f813d864406a6480cccdb5d7370",["Text"]="-----------------------------------\n-- ID: 5185\n-- Item: leremieu_salad\n-- Food Effect: 240Min, All Races\n-----------------------------------\n-- Health 20\n-- Magic 20\n-- Dexterity 4\n-- Agility 4\n-- Vitality 6\n-- Charisma 4\n-- Defense % 25\n-- Defense Cap 160\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 20)\n    effect:addMod(xi.mod.FOOD_MP, 20)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.AGI, 4)\n    effect:addMod(xi.mod.VIT, 6)\n    effect:addMod(xi.mod.CHR, 4)\n    effect:addMod(xi.mod.FOOD_DEFP, 25)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 160)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/leremieu_taco.lua"]={["Path"]="scripts/items/leremieu_taco.lua",["SHA256"]="4a23f953d466017c891671735b29d5b47c49055fd964e830e756251f28ec3a0c",["Text"]="-----------------------------------\n-- ID: 5175\n-- Item: leremieu_taco\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Health 20\n-- Magic 20\n-- Dexterity 4\n-- Agility 4\n-- Vitality 6\n-- Charisma 4\n-- Health Regen While Healing 1\n-- Magic Regen While Healing 1\n-- Defense % 25\n-- Defense Cap 160\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 20)\n    effect:addMod(xi.mod.FOOD_MP, 20)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.AGI, 4)\n    effect:addMod(xi.mod.VIT, 6)\n    effect:addMod(xi.mod.CHR, 4)\n    effect:addMod(xi.mod.HPHEAL, 1)\n    effect:addMod(xi.mod.MPHEAL, 1)\n    effect:addMod(xi.mod.FOOD_DEFP, 25)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 160)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/leviathans_rod.lua"]={["Path"]="scripts/items/leviathans_rod.lua",["SHA256"]="5273bf57cb578eb68422294225a067598ac452305329ba00e9ea60da0a0af803",["Text"]="-----------------------------------\n-- ID: 17439\n-- Item: Leviathan's Rod\n-- Additional effect: water damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local chance = 3 -- TODO: check scaling on non-watersday\n\n    if VanadielDayOfTheWeek() == xi.day.WATERSDAY then\n        chance = xi.additionalEffect.linearProcRate(dStat, 140, 15, 50) -- Numbers are smoothed out a bit. Scale from 15% at dINT 0 to 50% at +140 DINT\n    end\n\n    local pTable =\n    {\n        chance         = chance,\n        basePower      = math.randomInt(18, 25),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WATER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/lieutenants_cape.lua"]={["Path"]="scripts/items/lieutenants_cape.lua",["SHA256"]="799ea4f09f2bfb0dcc31a1e40bee47df38c751a2e28cf1a1ea58a407cda0a36b",["Text"]="-----------------------------------\n-- ID: 16230\n-- Item: Lieutenant's Cape\n-- Item Effect: Restores 50% hp and 25% mp\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addHP((target:getMaxHP() / 100) * 50)\n    target:addMP((target:getMaxMP() / 100) * 25)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP_AND_MP)\nend\n\nreturn itemObject\n"},["scripts/items/lieutenants_sash.lua"]={["Path"]="scripts/items/lieutenants_sash.lua",["SHA256"]="90146c32e437ee3246dc5c23d5585ea71076c164339e4f4d714126fa4e75587a",["Text"]="-----------------------------------\n-- ID: 15912\n-- Item: Lieutenant's Sash\n-- On Use: Removes food effect.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:delStatusEffect(xi.effect.FOOD)\nend\n\nreturn itemObject\n"},["scripts/items/light_card_case.lua"]={["Path"]="scripts/items/light_card_case.lua",["SHA256"]="ec0466b839c6915222ab39bf3e30460b0430fb3810605db0d5db75aa8b63f7de",["Text"]="-----------------------------------\n-- ID: 5408\n-- Light Card Case\n-- When used, you will obtain one stack of Light Cards\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.LIGHT_CARD, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/light_cluster.lua"]={["Path"]="scripts/items/light_cluster.lua",["SHA256"]="44c5537e55e3a22c059ead4660f8b4de0810ef8ec48489db7b6190c51931f484",["Text"]="-----------------------------------\n-- ID: 4110\n-- Light Cluster\n-- Turn into a stack of light crystals\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.LIGHT_CRYSTAL, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/light_spirit_pact.lua"]={["Path"]="scripts/items/light_spirit_pact.lua",["SHA256"]="5f2e07c5dc2b306fdf4998ed4fa439239d28d0e7444e4aedb95f94633b1e055a",["Text"]="-----------------------------------\n-- ID: 4902\n-- Light Spirit Pact\n-- Teaches the summoning magic Air Spirit\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.LIGHT_SPIRIT)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.LIGHT_SPIRIT)\nend\n\nreturn itemObject\n"},["scripts/items/light_staff.lua"]={["Path"]="scripts/items/light_staff.lua",["SHA256"]="4840c6f7eea66fdd51d09c3c7f4a004602d3b2795273d9e5f0e634f8cd4ea3ac",["Text"]="-----------------------------------\n-- ID: 17557\n-- Item: Light Staff\n-- Additional effect: light damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 15, -- guessed\n        basePower      = math.randomInt(12, 16),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/lightning_arrow.lua"]={["Path"]="scripts/items/lightning_arrow.lua",["SHA256"]="7e5546af372cfcfcf25aa1ac0554045e05d75b63c7b4ed5b709a75f8b774c26e",["Text"]="-----------------------------------\n-- ID: 17324\n-- Item: Lightning Arrow\n-- Additional effect: Lightning damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    -- Unconfirmed power.\n    local pTable =\n    {\n        ignoreEnSpell   = true,\n        basePower       = math.random(7, 10),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.THUNDER,\n        canResist       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/lightning_cluster.lua"]={["Path"]="scripts/items/lightning_cluster.lua",["SHA256"]="c0a0d82e9d878ee2e84f3cf5a327c07bf0bc67634cb719ed2fb08fdaa8e9e5a2",["Text"]="-----------------------------------\n-- ID: 4108\n-- Lighting Cluster\n-- Turn into a stack of lighting crystals\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.LIGHTNING_CRYSTAL, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/lik_kabob.lua"]={["Path"]="scripts/items/lik_kabob.lua",["SHA256"]="28c04b63c78879bdb4fcd57c2c31f99a882ebe2778dd4acbf1d7c434be6f33b4",["Text"]="-----------------------------------\n-- ID: 5647\n-- Item: Lik Kabob\n-- Food Effect: 30 Min, All Races\n-----------------------------------\n-- Dexterity 3\n-- Mind -2\n-- Accuracy +1\n-- Attack 7\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.MND, -2)\n    effect:addMod(xi.mod.ACC, 1)\n    effect:addMod(xi.mod.ATT, 7)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/linen_coin_purse.lua"]={["Path"]="scripts/items/linen_coin_purse.lua",["SHA256"]="18c46c8588d0658d70c1443d9e89bf21041cab0b8011472cd8961cc52e455723",["Text"]="-----------------------------------\n-- ID: 5736\n-- Lin. Purse (Alx.)\n-- Breaks up a Linen Purse\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ALEXANDRITE, math.randomInt(50, 99) } })\nend\n\nreturn itemObject\n"},["scripts/items/lionhead.lua"]={["Path"]="scripts/items/lionhead.lua",["SHA256"]="49b83e31e5a99ae903ad58d6381d0d2f02e02a9ec15899a16a530fef9446d033",["Text"]="-----------------------------------\n-- ID: 4312\n-- Item: lionhead\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/little_comet.lua"]={["Path"]="scripts/items/little_comet.lua",["SHA256"]="ac7793faea36004befa99058d8945ec6c8c73fe205fa19757fa0b21ee6dec23f",["Text"]="-----------------------------------\n-- ID: 4169\n-- Little Comet\n-- Several sparkles rise and fall, twinkling steadily\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/little_worm_belt.lua"]={["Path"]="scripts/items/little_worm_belt.lua",["SHA256"]="f4b454786b362188c9eff5e4e664bbabdfe733ec1e849fd9a6c14ed040888007",["Text"]="-----------------------------------\n-- ID: 15454\n-- little_worm_belt\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.LITTLE_WORM, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/lizard_egg.lua"]={["Path"]="scripts/items/lizard_egg.lua",["SHA256"]="d3e05483511083c1a62f1bee5945a92ad303a5c9521ed0f1d88770f1f61eeb01",["Text"]="-----------------------------------\n-- ID: 4362\n-- Item: lizard_egg\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Health 5\n-- Magic 5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 5)\n    effect:addMod(xi.mod.FOOD_MP, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/lizard_piercer.lua"]={["Path"]="scripts/items/lizard_piercer.lua",["SHA256"]="311b1acfb603c17dc2fba68222f6ade083ffee8167f16362f9300b215359dbde",["Text"]="-----------------------------------\n-- ID: 16853\n-- Item: Lizard Piercer\n-- Additional effect: ice damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    if not target:isMob() or target:getFamily() ~= xi.mobFamily.LIZARD then\n        return 0, 0, 0\n    end\n\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 5 + utils.clamp(dStat * 5 / 54, 0, 5), -- 5% over 54\n        basePower      = math.randomInt(6, 8),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.ICE,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/loaf_of_black_bread.lua"]={["Path"]="scripts/items/loaf_of_black_bread.lua",["SHA256"]="e2e1fab3224699e9043af4ecd0c00df68ba62a58decaac662aace2697a7a141a",["Text"]="-----------------------------------\n-- ID: 4364\n-- Item: loaf_of_black_bread\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health 8\n-- Dexterity -1\n-- Vitality 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 8)\n    effect:addMod(xi.mod.DEX, -1)\n    effect:addMod(xi.mod.VIT, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/loaf_of_goblin_bread.lua"]={["Path"]="scripts/items/loaf_of_goblin_bread.lua",["SHA256"]="4ccda01e05920d6a0be06dd33708a0017220faca0d811f9dc88e9edfffa8fad0",["Text"]="-----------------------------------\n-- ID: 4458\n-- Item: loaf_of_goblin_bread\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health 7\n-- Vitality 1\n-- Charisma -5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 7)\n    effect:addMod(xi.mod.VIT, 1)\n    effect:addMod(xi.mod.CHR, -5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/loaf_of_hobgoblin_bread.lua"]={["Path"]="scripts/items/loaf_of_hobgoblin_bread.lua",["SHA256"]="3526ef6a1678e5aa29ea9dcea6e7a0578131138fb26bd5470ae7d878b41486d5",["Text"]="-----------------------------------\n-- ID: 4328\n-- Item: loaf_of_hobgoblin_bread\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Health 10\n-- Vitality 3\n-- Charisma -7\n-- Health Regen While Healing 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.CHR, -7)\n    effect:addMod(xi.mod.HPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/loaf_of_homemade_bread.lua"]={["Path"]="scripts/items/loaf_of_homemade_bread.lua",["SHA256"]="5dc0b31a7abc0edff358afa03cdf3de2fd2dd149213202895a3029ee967f527d",["Text"]="-----------------------------------\n-- ID: 5228\n-- Item: loaf_of_homemade_bread\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- hMP +1\n-- Accuracy +12% (cap 80)\n-- Attack +10% (cap 40)\n-- Ranged Accuracy +12% (cap 80)\n-- Ranged Attack +10% (cap 40)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MPHEAL, 1)\n    effect:addMod(xi.mod.FOOD_ACCP, 12)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_ATTP, 10)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 40)\n    effect:addMod(xi.mod.FOOD_RACCP, 12)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_RATTP, 10)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 40)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/loaf_of_iron_bread.lua"]={["Path"]="scripts/items/loaf_of_iron_bread.lua",["SHA256"]="adbf94c914c145dd713ef56a22cd3d8791155a5d14c42b8aef767bcb8db288c3",["Text"]="-----------------------------------\n-- ID: 4499\n-- Item: loaf_of_iron_bread\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health 4\n-- Vitality 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 4)\n    effect:addMod(xi.mod.VIT, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/loaf_of_pain_de_neige.lua"]={["Path"]="scripts/items/loaf_of_pain_de_neige.lua",["SHA256"]="a0ed4f5fa99e33bf0b14eef83f4eea8e20e30374245054dde9d147939d1beb1c",["Text"]="-----------------------------------\n-- ID: 4292\n-- Item: loaf_of_pain_de_neige\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Health 18\n-- Vitality 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 18)\n    effect:addMod(xi.mod.VIT, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"}};
